func lsfEntryOf[K any, V any](k K, v V) *lsfEntry[K, V] {
	return &lsfEntry[K, V]{k, v}
}

func lsfKeyValOf[K any, V any](es *lsfList[*lsfEntry[K, V]], cmp func(K, K) int) *lsfMap[K, V] {
	var m *lsfMap[K, V]
	for c := es; c != nil; c = c.tail {
		m = lsfPut(m, c.head.fKey, c.head.fValue, cmp)
	}
	return m
}

func lsfOrderingOf(c int) lsfOrdering {
	if c < 0 {
		return lsfOrdering_Less
	}
	if c == 0 {
		return lsfOrdering_Equal
	}
	return lsfOrdering_Greater
}

