func lsfFromValueEitherTextEnv(v LawSpecValue) lsfEither[string, *lsfEnv] {
	tag, fields := lsfData(v)
	if tag == "Either::Right" {
		return lsfRight[string, *lsfEnv](lsfFromValueEnv(fields[0]))
	}
	return lsfLeft[string, *lsfEnv](lsfFromValueText(fields[0]))
}

