func lsfFromValueBreaker(v LawSpecValue) lsfBreaker {
	tag, fields := lsfData(v)
	switch tag {
	case "lawspec.resilience::type::Breaker::Closed":
		return &lsfBreaker_Closed{lsfFromValueListInteger(fields[0])}
	case "lawspec.resilience::type::Breaker::Open":
		return &lsfBreaker_Open{lsfFromValueInteger(fields[0])}
	case "lawspec.resilience::type::Breaker::HalfOpen":
		return &lsfBreaker_HalfOpen{}
	}
	panic("expected Breaker, found " + tag)
}

