func lsfFromNativeEitherTextEnv(n LawSpecEither[string, Env]) lsfEither[string, *lsfEnv] {
	if r, ok := n.Right(); ok {
		return lsfRight[string, *lsfEnv](lsfFromNativeEnv(r))
	}
	l, _ := n.Left()
	return lsfLeft[string, *lsfEnv](lsfFromNativeText(l))
}

