func lsfToValueBreaker(x lsfBreaker) LawSpecValue {
	switch y := x.(type) {
	case *lsfBreaker_Closed:
		return lsfDataValue("lawspec.resilience::type::Breaker", "lawspec.resilience::type::Breaker::Closed", lsfToValueListInteger(y.fValue))
	case *lsfBreaker_Open:
		return lsfDataValue("lawspec.resilience::type::Breaker", "lawspec.resilience::type::Breaker::Open", lsfToValueInteger(y.fValue))
	case *lsfBreaker_HalfOpen:
		return lsfDataValue("lawspec.resilience::type::Breaker", "lawspec.resilience::type::Breaker::HalfOpen")
	}
	panic("unreachable branch reached")
}

