	if a == b {
		return true
	}
	return true && lsfEqualComplexity(a.fComplexity, b.fComplexity) && lsfEqualMaybeSignature(a.fSignature, b.fSignature) && a.fTypeKind == b.fTypeKind && a.fUnderlying == b.fUnderlying && a.fTypeText == b.fTypeText && lsfEqualMaybeBool(a.fInAll, b.fInAll) && lsfEqualListText(a.fDecorators, b.fDecorators) && lsfEqualListText(a.fConcerns, b.fConcerns) && lsfEqualBinary(a.fBinary, b.fBinary)
