func lsfCompareMaybeInteger(a, b lsfMaybe[lsfInt]) int {
	if a.ok != b.ok {
		if a.ok {
			return 1
		}
		return -1
	}
	if !a.ok {
		return 0
	}
	return lsfCompareInteger(a.v, b.v)
}

